// Solution : utiliser le nœud parent qui a été exécuté
const userMessage = $('Podcast Script Agent').first().json.output || 
                    $input.first().json.chatInput || 
                    'podcast_episode';

// Générer un titre court et propre
const generateTitle = (text) => {
  // Nettoyer et limiter à 5-6 mots max
  const words = text
    .toLowerCase()
    .replace(/[^\w\s]/g, '') // Retirer ponctuation
    .split(' ')
    .filter(word => word.length > 3) // Garder mots significatifs
    .slice(0, 5); // Max 5 mots

  return words.join('_');
};

const title = generateTitle(userMessage);
const timestamp = new Date().toISOString().split('T')[0]; // Format: YYYY-MM-DD

return {
  json: {
    ...($input.first().json),
    fileName: `${title}_${timestamp}.mp3`
  }
};

